   function updateSaveState(){var status=document.getElementById('saveState'),dirty=savedSnapshot!==configurationSnapshot(),reason=saveBlockReason();status.className='save-state'+(reason?' error':dirty?' dirty':'');status.textContent=reason|| (dirty?'Modified':'Saved');status.title=DATA.boardPinmux.issues.length?'Loaded BSP has '+DATA.boardPinmux.issues.length+' parse issue(s).':reason;document.getElementById('applyBsp').disabled=Boolean(reason);document.getElementById('saveBspAs').disabled=Boolean(reason);document.getElementById('undo').disabled=historyPast.length===0;document.getElementById('redo').disabled=historyFuture.length===0;document.getElementById('clearAll').disabled=configuredPins().length===0;}
